from pathlib import Path
import base64, hashlib, subprocess, sys, zlib

root = Path(sys.argv[1]).resolve()
payload = ""
patch = zlib.decompress(base64.b64decode(payload))
expected = "3e56ceabc01338d9caf461fb28125a7a8512cce61938227b60aa4392b3c921df"
actual = hashlib.sha256(patch).hexdigest()
if actual != expected:
    raise RuntimeError(f"alpha50 patch checksum mismatch: {actual} != {expected}")

subprocess.run(["git", "-C", str(root), "apply", "--whitespace=nowarn", "-"], input=patch, check=True)
print("PKVault V8 alpha50 transactional trash + immediate quest item persistence applied")
